<aside class="builder-inspector"><h2>Настройки поля</h2><p id="builder-inspector-empty">Выберите поле в макете для настройки.</p><div id="builder-inspector-controls" hidden><label>Подпись<input id="builder-label" placeholder="Название поля"></label><label>Системное имя<input id="builder-name" placeholder="field_name" pattern="[a-zA-Z][a-zA-Z0-9_]*"></label><label>Тип поля<select id="builder-type"><option value="text">Текст</option><option value="email">Email</option><option value="tel">Телефон</option><option value="textarea">Большой текст</option><option value="select">Выпадающий список</option></select></label><label class="builder-required"><input type="checkbox" id="builder-required"> Обязательное поле</label><label id="builder-options-wrap" hidden>Варианты ответа (по одному в строке)<textarea id="builder-options" rows="5"></textarea></label><button type="button" id="builder-remove">Удалить поле</button></div>@if($record)<a class="builder-public-link" href="{{route('forms.show',$record->slug)}}" target="_blank" rel="noopener">Открыть опубликованную форму ↗</a>@endif</aside>
</div>
<textarea id="builder-json" name="fields_json" hidden required>{{old('fields_json',json_encode($record?->fields??[['name'=>'name','label'=>'Имя','type'=>'text','required'=>true],['name'=>'email','label'=>'E-mail','type'=>'email','required'=>true],['name'=>'message','label'=>'Сообщение','type'=>'textarea','required'=>true]],JSON_UNESCAPED_UNICODE))}}</textarea>
</form>
<script>
(()=>{'use strict';
const root=document.getElementById('visual-form-builder'),raw=document.getElementById('builder-json'),list=document.getElementById('builder-field-list'),controls=document.getElementById('builder-inspector-controls'),empty=document.getElementById('builder-inspector-empty');
const label=document.getElementById('builder-label'),name=document.getElementById('builder-name'),type=document.getElementById('builder-type'),required=document.getElementById('builder-required'),options=document.getElementById('builder-options'),optionsWrap=document.getElementById('builder-options-wrap');
const names={text:'Текст',email:'Email',tel:'Телефон',textarea:'Большой текст',select:'Список'};
let fields=[];try{const parsed=JSON.parse(raw.value);if(Array.isArray(parsed))fields=parsed}catch(e){root.insertAdjacentHTML('afterbegin','<p role="alert">Не удалось прочитать поля формы.</p>');return}
let selected=fields.length?0:-1,preview=false,dragFrom=-1;
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function sync(){raw.value=JSON.stringify(fields);document.getElementById('builder-field-count').textContent=fields.length+' полей'}
function inspect(){const f=fields[selected];controls.hidden=!f;empty.hidden=!!f;if(!f)return;label.value=f.label??'';name.value=f.name??'';type.value=names[f.type]?f.type:'text';required.checked=!!f.required;optionsWrap.hidden=f.type!=='select';options.value=(f.options??[]).join('\n')}
function render(){list.replaceChildren();fields.forEach((f,i)=>{const card=document.createElement('div');card.className='builder-field'+(selected===i?' is-selected':'');card.draggable=!preview;card.dataset.index=i;card.innerHTML='<div class="builder-field-toolbar"><span class="builder-drag" title="Перетащить">⠿</span><strong>'+(i+1)+'. '+safe(f.label||'Без названия')+'</strong><span>'+safe(names[f.type]||f.type)+'</span><button type="button" data-move="up" aria-label="Выше">↑</button><button type="button" data-move="down" aria-label="Ниже">↓</button></div><label>'+safe(f.label||'Поле')+(f.required?' <b>*</b>':'')+'</label><div class="builder-field-control"></div>';const slot=card.querySelector('.builder-field-control');let input;if(f.type==='textarea'){input=document.createElement('textarea');input.rows=3}else if(f.type==='select'){input=document.createElement('select');const opt=document.createElement('option');opt.textContent='Выберите';input.append(opt);(f.options??[]).forEach(v=>{const o=document.createElement('option');o.textContent=v;input.append(o)})}else{input=document.createElement('input');input.type=['email','tel'].includes(f.type)?f.type:'text';input.placeholder='Введите '+(f.label||'значение').toLowerCase()}input.disabled=true;slot.append(input);card.addEventListener('click',e=>{if(preview||e.target.closest('[data-move]'))return;selected=i;render()});card.querySelectorAll('[data-move]').forEach(btn=>btn.addEventListener('click',()=>{const j=i+(btn.dataset.move==='up'?-1:1);if(j<0||j>=fields.length)return;[fields[i],fields[j]]=[fields[j],fields[i]];selected=j;render()}));card.addEventListener('dragstart',e=>{dragFrom=i;e.dataTransfer.effectAllowed='move'});card.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='move'});card.addEventListener('drop',e=>{e.preventDefault();if(dragFrom<0||dragFrom===i)return;const moved=fields.splice(dragFrom,1)[0];fields.splice(i,0,moved);selected=i;dragFrom=-1;render()});list.append(card)});document.getElementById('builder-empty').hidden=fields.length>0;document.getElementById('builder-canvas-title').textContent=preview?'Как увидит посетитель':'Редактирование макета';root.classList.toggle('builder-preview-mode',preview);inspect();sync()}
document.querySelectorAll('[data-add]').forEach(btn=>btn.addEventListener('click',()=>{const t=btn.dataset.add;const used=new Set(fields.map(f=>f.name));let n='field_'+(fields.length+1);while(used.has(n))n+='x';fields.push({name:n,label:names[t],type:t,required:false,...(t==='select'?{options:['Вариант 1','Вариант 2']}: {})});selected=fields.length-1;preview=false;render()}));
label.addEventListener('input',()=>{if(fields[selected]){fields[selected].label=label.value;render()}});
name.addEventListener('input',()=>{if(fields[selected]){fields[selected].name=name.value;sync()}});
type.addEventListener('change',()=>{if(fields[selected]){fields[selected].type=type.value;if(type.value==='select'&&!fields[selected].options)fields[selected].options=['Вариант 1','Вариант 2'];render()}});
required.addEventListener('change',()=>{if(fields[selected]){fields[selected].required=required.checked;render()}});
options.addEventListener('input',()=>{if(fields[selected]){fields[selected].options=options.value.split('\n').map(v=>v.trim()).filter(Boolean);sync()}});
document.getElementById('builder-remove').addEventListener('click',()=>{if(selected<0)return;fields.splice(selected,1);selected=Math.min(selected,fields.length-1);render()});
document.getElementById('builder-preview-toggle').addEventListener('click',e=>{preview=!preview;e.currentTarget.textContent=preview?'Вернуться к редактированию':'Предпросмотр';render()});
root.addEventListener('submit',e=>{const seen=new Set();for(const f of fields){if(!/^[a-zA-Z][a-zA-Z0-9_]*$/.test(f.name||'')||f.name==='privacy'||seen.has(f.name)){e.preventDefault();alert('Проверьте системные имена полей: латинские буквы, цифры, _, без повторений и privacy.');return}seen.add(f.name)}sync()});
render();
})();
</script>
@endsection